28	// dependencyKey groups dependency links by (parent, child) for merging.
29	type dependencyKey struct {
30		parent string
31		child  string
32	}
33	
34	func (r *Reader) GetDependencies(ctx context.Context, query depstore.QueryParameters) ([]model.DependencyLink, error) {
35		rows, err := r.conn.Query(ctx, sql.SelectDependencies, query.StartTime, query.EndTime)
36		if err != nil {
37			return nil, fmt.Errorf("failed to query dependencies: %w", err)
38		}
39		defer rows.Close()
40	
41		// Merge dependencies from all snapshots in the time range.
42		merged := make(map[dependencyKey]uint64)
43	
44		for rows.Next() {
45			var blob string
46			if err := rows.Scan(&blob); err != nil {
47				return nil, fmt.Errorf("failed to scan dependency row: %w", err)
48			}
49			var links []dependencyLink
50			if err := json.Unmarshal([]byte(blob), &links); err != nil {
51				return nil, fmt.Errorf("failed to unmarshal dependencies JSON: %w", err)
52			}
53			for _, link := range links {
54				merged[dependencyKey{link.Parent, link.Child}] += link.CallCount
55			}
56		}
57	
58		if len(merged) == 0 {
59			return nil, nil
60		}
61	
62		dependencies := make([]model.DependencyLink, 0, len(merged))
63		for k, callCount := range merged {
64			dependencies = append(dependencies, model.DependencyLink{
65				Parent:    k.parent,
66				Child:     k.child,
67				CallCount: callCount,
68			})
69		}
70		return dependencies, nil
71	}
