var errNotImplemented = errors.New("not implemented")

// defaultStepSeconds is the fallback step size, in seconds, used when the query
// parameters do not specify a valid step duration.
const defaultStepSeconds uint64 = 60

// spanKindMapping maps OpenTelemetry span kind names to the ClickHouse-stored
// lowercase representation.
var spanKindMapping = map[string]string{
	"SPAN_KIND_SERVER":      "server",
	"SPAN_KIND_CLIENT":      "client",
	"SPAN_KIND_UNSPECIFIED": "",
}

// Reader is a ClickHouse-backed implementation of the metricstore.Reader
// interface. It loads aggregated Service Performance Monitoring (SPM) metrics
// from a ClickHouse database.
type Reader struct {
	conn driver.Conn
}

// NewReader returns a new Reader that reads aggregated metrics from ClickHouse
// using the provided driver connection.
func NewReader(conn driver.Conn) *Reader {
	return &Reader{conn: conn}
}

// GetLatencies loads latency metrics for the requested services, optionally
// grouped by operation.
func (r *Reader) GetLatencies(ctx context.Context, params *metricstore.LatenciesQueryParameters) (*metrics.MetricFamily, error) {
	query := sql.SelectLatencies
	name := "service_latencies"
	if params.GroupByOperation {
		query = sql.SelectLatenciesByOperation
		name = "service_operation_latencies"
