		query,
		stepSeconds(params.BaseQueryParameters),
		params.Quantile,
		params.ServiceNames,
		start,
		end,
		convertSpanKinds(params.SpanKinds),
	)
	if err != nil {
		return nil, fmt.Errorf("failed to query latencies: %w", err)
