// toMetricFamily reads all rows and assembles them into a MetricFamily. Rows
// belonging to the same time series (identified by service name and, when
// grouping by operation, the operation name) are merged into a single Metric
// with one MetricPoint per row, preserving the order in which series first
// appear.
func toMetricFamily(name string, rows driver.Rows, groupByOperation bool) (*metrics.MetricFamily, error) {
	family := &metrics.MetricFamily{
		Name: name,
		Type: metrics.MetricType_GAUGE,
	}

	type seriesKey struct {
		serviceName string
		operation   string
	}
	index := make(map[seriesKey]*metrics.Metric)

	for rows.Next() {
		var row metricsRow
		if err := rows.ScanStruct(&row); err != nil {
			return nil, fmt.Errorf("failed to scan metrics row: %w", err)
		}

		key := seriesKey{serviceName: row.ServiceName}
		if groupByOperation {
			key.operation = row.Operation
		}

		metric, ok := index[key]
		if !ok {
			labels := []*metrics.Label{
				{Name: "service_name", Value: row.ServiceName},
			}
			if groupByOperation {
				labels = append(labels, &metrics.Label{Name: "operation", Value: row.Operation})
			}
			metric = &metrics.Metric{Labels: labels}
			index[key] = metric
			family.Metrics = append(family.Metrics, metric)
		}

		metric.MetricPoints = append(metric.MetricPoints, &metrics.MetricPoint{
			Timestamp: toDomainTimestamp(row.Timestamp),
			Value: &metrics.MetricPoint_GaugeValue{
				GaugeValue: &metrics.GaugeValue{
					Value: &metrics.GaugeValue_DoubleValue{DoubleValue: row.Value},
				},
			},
		})
	}

	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("error iterating metrics rows: %w", err)
	}

	return family, nil
}

// toDomainTimestamp converts a time.Time into the protobuf timestamp used by
// the metrics domain model.
func toDomainTimestamp(t time.Time) *types.Timestamp {
	return &types.Timestamp{
		Seconds: t.Unix(),
		Nanos:   int32(t.Nanosecond()),
	}
}

// timeRange derives the [start, end] time range for a query from the base
// query parameters. It defaults the end time to now when unset and applies the
// configured lookback to compute the start time.
func timeRange(p metricstore.BaseQueryParameters) (time.Time, time.Time) {
	end := time.Now()
	if p.EndTime != nil {
		end = *p.EndTime
	}
	start := end
	if p.Lookback != nil {
		start = end.Add(-*p.Lookback)
	}
	return start, end
}

// stepSeconds converts the Step field of the base query parameters into whole
// seconds. It returns defaultStepSeconds when Step is nil, zero, or negative,
// clamps positive sub-second durations up to 1, and truncates any fractional
// seconds.
func stepSeconds(p metricstore.BaseQueryParameters) uint64 {
	if p.Step == nil || *p.Step <= 0 {
		return defaultStepSeconds
	}
	if *p.Step < time.Second {
		return 1
	}
	return uint64(*p.Step / time.Second)
}

// convertSpanKinds converts OpenTelemetry span kind names into the
// ClickHouse-stored lowercase representation. Unrecognized kinds are omitted
// from the result.
func convertSpanKinds(kinds []string) []string {
	converted := make([]string, 0, len(kinds))
	for _, kind := range kinds {
		if v, ok := spanKindMapping[kind]; ok {
			converted = append(converted, v)
		}
	}
	return converted
}
